sys_script_include.script:
var IncentIQAuditMaintenance = Class.create();
IncentIQAuditMaintenance.prototype = {

    initialize: function() {
        this.LOG = 'IncentIQAuditMaintenance :: ';
    },

    purgeOldAudit: function() {
        var days = parseInt(gs.getProperty('x_ctans_incentnow.audit_retention_days', '90'), 10);
        if (isNaN(days) || days <= 0) {
            gs.info(this.LOG + 'Retention disabled (audit_retention_days <= 0). Nothing purged.');
            return 0;
        }

        var cutoff = new GlideDateTime();
        cutoff.addSeconds(-1 * days * 86400);
        var cutoffStr = cutoff.getValue();

        var BATCH = 10000; // rows per pass — bounds each transaction
        var MAX_PASSES = 500; // safety cap: up to 5M rows per run
        var totalDeleted = 0;

        for (var pass = 0; pass < MAX_PASSES; pass++) {
            var gr = new GlideRecord('x_ctans_incentnow_incentiq_ai_audit');
            gr.addQuery('sys_created_on', '<', cutoffStr);
            gr.setLimit(BATCH);
            gr.query();
            if (!gr.hasNext()) {
                break;
            }
            var passCount = 0;
            while (gr.next()) {
                gr.deleteRecord();
                passCount++;
            }
            totalDeleted += passCount;
            if (passCount < BATCH) {
                break;
            } // last partial batch
        }

        gs.info(this.LOG + 'Purged ' + totalDeleted + ' audit rows older than ' + days + ' days (before ' + cutoffStr + ').');
        return totalDeleted;
    },

    type: 'IncentIQAuditMaintenance'
};
